// 2. REQUEST VALIDATION
const items = Array.isArray(input) ? input : (input?.items || [input]);
const raw = items[0]?.json || items[0] || {};
const body = raw.body || raw;
const headers = raw.headers || {};

const requestId = 'req_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
let action = (body.action || raw.action || '').trim().toLowerCase();
if (action.startsWith('/')) action = action.substring(1);
if (!action && (body.budget || body.bedrooms || body.propertyType)) action = 'matching/buyer';

return {
  json: {
    requestId,
    timestamp: new Date().toISOString(),
    action,
    clientIp: headers['x-forwarded-for'] || 'unknown',
    authorization: headers.authorization || headers.token || body.token || null,
    body: { ...body }
  }
};

// 3. ACTION ROUTER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const action = item?.action || '';

const routeDomain = (act) => {
  if (act.startsWith('auth/')) return 'AUTH';
  if (act.startsWith('seller/') || act.startsWith('properties/')) return 'SELLER';
  if (act.startsWith('shortlists/') || act.startsWith('interests/') || 
      act.startsWith('connections/') || act.startsWith('visits/') || 
      act.startsWith('messages/') || act.startsWith('feedback/') || 
      act.startsWith('location/')) return 'INTERACTIONS';
  return 'BUYER_MATCHING';
};

return {
  json: {
    ...item,
    domain: routeDomain(action),
    routedAt: new Date().toISOString()
  }
};

// 4. ERROR HANDLER
const items = Array.isArray(input) ? input : (input?.items || [input]);
const incoming = items[0]?.json || items[0] || {};

return {
  json: {
    success: false,
    action: incoming.action || 'unknown',
    data: null,
    error: {
      code: incoming.error?.code || 'VALIDATION_ERROR',
      message: incoming.error?.message || 'Invalid request payload or processing failed'
    },
    requestId: incoming.requestId || ('req_' + Date.now())
  }
};

// 5. AUTHENTICATION MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
const action = item?.action || '';

const role = (body.role || 'BUYER').toUpperCase();
const intent = body.intent || (role === 'SELLER' ? 'SELL' : 'BUY');

return {
  json: {
    success: true,
    action,
    data: {
      userId: body.userId || ('usr_' + Date.now()),
      email: body.email || '',
      name: body.name || 'HavenMatch User',
      role,
      intent,
      token: 'hm_session_' + Buffer.from(body.email + ':' + Date.now()).toString('base64'),
      verified: true
    },
    requestId: item.requestId
  }
};

// 6. BUYER PROFILE & LIFESTYLE
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};

const buyerProfile = {
  buyerId: body.buyerId || body.userId || ('buyer_' + Date.now()),
  intent: (body.intent || 'BUY').toUpperCase(),
  budget: {
    min: Number(body.budgetMin !== undefined ? body.budgetMin : (body.budget?.min || 0)),
    max: Number(body.budgetMax !== undefined ? body.budgetMax : (body.budget?.max || 100000000))
  },
  bedrooms: Array.isArray(body.bedrooms) ? body.bedrooms : (body.bedrooms ? [body.bedrooms] : []),
  propertyTypes: Array.isArray(body.propertyTypes) ? body.propertyTypes : (body.propertyType ? [body.propertyType] : []),
  city: body.city || '',
  preferredLocalities: Array.isArray(body.preferredLocalities) ? body.preferredLocalities : (body.locality ? [body.locality] : []),
  lifestyle: {
    commute: body.commute || null,
    priorities: Array.isArray(body.lifestylePriorities) ? body.lifestylePriorities : (body.priorities || [])
  }
};

return {
  json: {
    ...item,
    buyerProfile
  }
};

// 8. HARD CONSTRAINT FILTER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const buyer = item.buyerProfile || {};
const inventory = item.properties || [];

const eligible = inventory.filter(prop => {
  if (prop.status && prop.status !== 'ACTIVE') return false;
  if (buyer.budget?.max && prop.price > buyer.budget.max) return false;
  if (buyer.budget?.min && prop.price < buyer.budget.min) return false;
  if (buyer.intent === 'BUY' && prop.listingType === 'RENT') return false;
  if (buyer.intent === 'RENT' && prop.listingType === 'SALE') return false;
  return true;
});

return {
  json: {
    ...item,
    eligibleProperties: eligible,
    totalEligible: eligible.length
  }
};

// 9. SOFT PREFERENCE & LOCATION INTELLIGENCE
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const buyer = item.buyerProfile || {};
const properties = item.eligibleProperties || [];

const enriched = properties.map(prop => {
  let locationScore = 75;
  let commuteMins = 15;
  if (prop.location?.coordinates && buyer.lifestyle?.commute?.coordinates) {
    const [lat1, lon1] = [prop.location.coordinates[1], prop.location.coordinates[0]];
    const [lat2, lon2] = [buyer.lifestyle.commute.coordinates[1], buyer.lifestyle.commute.coordinates[0]];
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLon/2)**2;
    const d = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    commuteMins = Math.round(d * 3);
    locationScore = Math.max(40, Math.min(100, Math.round(100 - commuteMins * 1.5)));
  }
  return {
    ...prop,
    telemetry: { locationScore, commuteMins }
  };
});

return {
  json: {
    ...item,
    enrichedProperties: enriched
  }
};

// 10. MATCH SCORING
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const buyer = item.buyerProfile || {};
const properties = item.enrichedProperties || [];

const scored = properties.map(prop => {
  let budgetScore = 25;
  if (buyer.budget?.max && prop.price) {
    const ratio = prop.price / buyer.budget.max;
    budgetScore = ratio <= 0.85 ? 30 : ratio <= 1.0 ? 25 : 15;
  }

  let bedroomScore = 20;
  if (buyer.bedrooms?.length && prop.bedrooms) {
    bedroomScore = buyer.bedrooms.includes(prop.bedrooms) ? 25 : 15;
  }

  const locationScore = Math.round(((prop.telemetry?.locationScore || 75) / 100) * 25);
  let lifestyleScore = 18;
  const matchedFactors = ['Budget alignment verified', 'Locality match'];
  const tradeOffs = [];

  const totalScore = budgetScore + bedroomScore + locationScore + lifestyleScore;

  return {
    propertyId: prop._id || prop.id || prop.propertyId,
    title: prop.title,
    price: prop.price,
    bedrooms: prop.bedrooms,
    locality: prop.locality,
    city: prop.city,
    matchScore: totalScore,
    scoreBreakdown: {
      budget: budgetScore,
      property: bedroomScore,
      location: locationScore,
      lifestyle: lifestyleScore
    },
    matchedFactors,
    tradeOffs
  };
});

return {
  json: {
    ...item,
    scoredProperties: scored
  }
};

// 12. RECOMMENDATIONS & WHY THIS PROPERTY
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const ranked = item.scoredProperties || [];

const recommendations = ranked.slice(0, 10).map((p, idx) => ({
  ...p,
  rank: idx + 1,
  whyThisProperty: `Top match (${p.matchScore}% score) matching your budget range and preferred lifestyle in ${p.locality || 'selected area'}.`,
  locationFit: `Within target commute and amenity zone.`
}));

return {
  json: {
    success: true,
    action: 'matching/buyer',
    data: {
      recommendations,
      totalMatches: recommendations.length,
      evaluatedAt: new Date().toISOString()
    },
    requestId: item.requestId
  }
};

// 13. SELLER PROFILE & PROPERTY MANAGEMENT
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
const action = item?.action || '';

return {
  json: {
    success: true,
    action,
    data: {
      sellerId: body.sellerId || body.userId,
      propertyId: body.propertyId || ('prop-' + Date.now()),
      status: 'ACTIVE',
      updatedAt: new Date().toISOString()
    },
    requestId: item.requestId
  }
};

// 14. COMPATIBLE BUYER MATCHING
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};

return {
  json: {
    success: true,
    action: 'seller/compatible-buyers',
    data: {
      propertyId: body.propertyId,
      sellerId: body.sellerId,
      compatibleBuyers: [],
      totalMatches: 0
    },
    requestId: item.requestId
  }
};

// 15. SHORTLIST MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
return {
  json: {
    success: true,
    action: item.action,
    data: { userId: body.userId || body.buyerId, propertyId: body.propertyId, shortlists: [] },
    requestId: item.requestId
  }
};

// 16. INTEREST MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
return {
  json: {
    success: true,
    action: item.action,
    data: { interestId: 'int-' + Date.now(), propertyId: body.propertyId, status: 'EXPRESSED' },
    requestId: item.requestId
  }
};

// 17. CONNECTION MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
const connId = 'conn-' + Date.now() + '-' + Math.random().toString(16).substring(2, 10);
return {
  json: {
    success: true,
    action: item.action,
    data: { connection_id: connId, buyerId: body.buyerId, sellerId: body.sellerId, status: 'ACCEPTED' },
    requestId: item.requestId
  }
};

// 18. VISIT MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
const visitData = body.visitData || body;
return {
  json: {
    success: true,
    action: item.action,
    data: {
      visitId: 'vis-' + Date.now(),
      propertyId: visitData.propertyId,
      buyerId: visitData.buyerId,
      sellerId: visitData.sellerId,
      status: visitData.status || 'SCHEDULED'
    },
    requestId: item.requestId
  }
};

// 19. MESSAGING MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
return {
  json: {
    success: true,
    action: item.action,
    data: { messageId: 'msg-' + Date.now(), propertyId: body.propertyId, senderId: body.senderId },
    requestId: item.requestId
  }
};

// 20. FEEDBACK MANAGER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
return {
  json: {
    success: true,
    action: item.action,
    data: { feedbackId: 'fb-' + Date.now(), rating: body.rating || 5 },
    requestId: item.requestId
  }
};

// 22. RESPONSE FORMATTER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
return {
  json: {
    success: item.success !== false,
    action: item.action || 'unknown',
    data: item.data || item,
    error: item.error || null,
    requestId: item.requestId || ('req_' + Date.now())
  }
};
